def solve_final(n):
    best_C = 0
    for p in range(1, n + 1):
        for q in range(1, n + 1):
            x_limit = min(n**2 / (2 * max(p, n-p)), n**2 / (2 * max(q, n-q)))

            points = [x_limit]
            if n-1 < x_limit: points.append(n-1)
            if n-p < x_limit: points.append(n-p)
            if q + n**2 - q*n > 0 and (q + n**2 - q*n) / (1 + n - q) < x_limit: 
                points.append((q + n**2 - q*n) / (1 + n - q))
            if q*p + n**2 - q*n > 0 and (q*p + n**2 - q*n) / (p + n - q) < x_limit: 
                points.append((q*p + n**2 - q*n) / (p + n - q))

            for x in points:
                if x > n/2 and x <= x_limit:
                    y = n - x
                    if x <= q + (n-q) * min(y, 1) and p*x <= q*p + (n-q) * min(p, y):
                        best_C = max(best_C, 2*x - n)
    return best_C

for n in range(2, 11):
    print(f"n={n}, C={solve_final(n)}")

