import numpy as np
from scipy.optimize import linprog

def check_fixed_S(S, n):
    if n % 2 == 0:
        R = np.array([S]* (n//2) + [-S]* (n//2))
        C = np.array([S]* (n//2) + [-S]* (n//2))
    else:
        if n == 3:
            R = np.array([S, S, -2*S])
            C = np.array([S, S, -2*S])
        elif n == 5:
            R = np.array([S, S, S, -S, -2*S])
            C = np.array([S, S, S, -S, -2*S])
        else:
            R = np.array([S]* (n//2) + [-S]* (n//2))
            C = np.array([S]* (n//2) + [-S]* (n//2))

    num_vars = n * n
    A_eq = []
    b_eq = []
    for i in range(n):
        row = [0] * num_vars
        for j in range(n):
            row[i * n + j] = 1
        A_eq.append(row)
        b_eq.append(R[i])
    for j in range(n):
        col = [0] * num_vars
        for i in range(n):
            col[i * n + j] = 1
        A_eq.append(col)
        b_eq.append(C[j])
    bounds = [(-1, 1)] * num_vars
    res = linprog(np.zeros(num_vars), A_eq=A_eq, b_eq=b_eq, bounds=bounds, method='highs')
    return res.success

for n in [2, 3, 4, 5]:
    low = 0
    high = n
    for _ in range(20):
        mid = (low + high) / 2
        if check_fixed_S(mid, n):
            low = mid
        else:
            high = mid
    print(f"n={n}, C={low}")

def find_max_x_correct_v5(n):
    def check_x(x, n):
        if n % 2 == 0:
            R = [x]* (n//2) + [-x]* (n//2)
            C = [x]* (n//2) + [-x]* (n//2)
        else:
            R = [x]* ((n+1)//2) + [-x]* ((n-3)//2) + [-2*x]
            C = [x]* ((n+1)//2) + [-x]* ((n-3)//2) + [-2*x]

        R_prime = sorted([(r + n)/2 for r in R], reverse=True)
        C_prime = sorted([(c + n)/2 for c in C], reverse=True)

        prefix_sum_R = 0
        for k in range(1, n+1):
            prefix_sum_R += R_prime[k-1]
            rhs = sum(min(k, c) for c in C_prime)
            if prefix_sum_R > rhs + 1e-9:
                return False
        return True

    low = 0.0
    high = n
    for _ in range(100):
        mid = (low + high) / 2
        if check_x(mid, n):
            low = mid
        else:
            high = mid
    return low

