def find_max_S(n):
    def check(S, n):
        r = [S + n] * (n - 1) + [-(n - 1) * S + n]
        r.sort(reverse=True)
        c = [S + n] * (n - 1) + [-(n - 1) * S + n]
        c.sort(reverse=True)
        for k in range(1, n + 1):
            left = sum(r[:k])
            right = sum(min(2 * k, c_j) for c_j in c)
            if left > right + 1e-9:
                return False
        return True

    low = 0
    high = n
    for _ in range(100):
        mid = (low + high) / 2
        if check(mid, n):
            low = mid
        else:
            high = mid
    return low

